/** Writes via the async clipboard API when available; falls back to a
 *  hidden textarea + execCommand for insecure origins (LAN preview over
 *  http), where navigator.clipboard is undefined. */
function writeClipboard(text: string): Promise<void> {
	if (navigator.clipboard?.writeText) {
		return navigator.clipboard.writeText(text);
	}
	return new Promise((resolve, reject) => {
		const ta = document.createElement("textarea");
		ta.value = text;
		ta.setAttribute("readonly", "");
		ta.style.position = "fixed";
		ta.style.opacity = "0";
		document.body.appendChild(ta);
		ta.select();
		const execCommand = Reflect.get(document, "execCommand") as
			| ((commandId: string) => boolean)
			| undefined;
