export function Frame(props: {
	children: ComponentChildren;
	id?: string;
	markBottom?: boolean;
	class?: string;
}) {
	return (
		<section
			class={`lp-fr ${props.markBottom ? "lp-mk-b" : ""} ${props.class ?? ""}`}
			id={props.id}
		>
			{props.children}
		</section>
