}

/** 26px hatched divider strip between framed sections. */
export function HatchBand() {
	return <div aria-hidden="true" class="lp-band" />;
}

/** Numeric section eyebrow: `[ 0N / LABEL ]` in tracked mono caps. */
export function NumEyebrow(props: { n: string; label: string }) {
	return (
		<span class="lp-eyebrow">
			[&nbsp;<span class="n">{props.n}</span>
			<span class="sl">/</span>
			{props.label}&nbsp;]
		</span>
	);
}

/** Standard section header: eyebrow + display heading + optional sub. */
export function SectionHead(props: {
	n: string;
	label: string;
	title: ComponentChildren;
	sub?: ComponentChildren;
}) {
	return (
		<Reveal class="lp-sec-h">
			<NumEyebrow label={props.label} n={props.n} />
			<h2>{props.title}</h2>
			{props.sub ? <p>{props.sub}</p> : null}
		</Reveal>
	);
}

/** FIG_0N caption plate under a figure card. */
export function FigCap(props: {
	n: string;
	label: string;
	extra?: string;
}) {
	return (
		<div class="lp-figcap">
			<span class="fn">{props.n}</span>
			<span>— {props.label}</span>
			{props.extra ? <span class="cp">{props.extra}</span> : null}
		</div>
	);
}
