import { loopContentFor, type LoopContent } from "./loop-content";
import connectorsManifest from "../../generated/connectors.json";

/** Generated manifest entry (feeds/actions are extracted from the real SDK
 *  connector source by scripts/gen-connectors.ts). */
type ManifestConnector = {
	key: string;
	name: string;
	feeds: { key: string; name: string }[];
	actions: { key: string; name: string; requiresApproval: boolean }[];
};
const MANIFEST = connectorsManifest as ManifestConnector[];
const manifestByKey: Record<string, ManifestConnector> = Object.fromEntries(
	MANIFEST.map((c) => [c.key, c]),
);

/** The demo derives connector ids from loop labels (e.g. "gmail", "drive"),
 *  which don't always match the generated manifest key ("google.gmail").
 *  This alias map bridges them; unknown ids fall back gracefully. */
const DEMO_ID_TO_MANIFEST: Record<string, string> = {
	gmail: "google.gmail",
	drive: "google.drive",
	calendar: "google.calendar",
	outlook: "microsoft.outlook",
};
function manifestFor(demoId: string): ManifestConnector | undefined {
	return manifestByKey[demoId] ?? manifestByKey[DEMO_ID_TO_MANIFEST[demoId] ?? ""];
}

