.lp-hero.has-windows h1 {
	font-size: 58px;
	max-width: 20ch;
	margin-top: 18px;
}
.lp-hero.has-windows .lead {
	max-width: 58ch;
	font-size: 17px;
	margin: 16px 0 22px;
}
.lp-hero.has-windows .cta {
	justify-content: center;
}

/* --- the stage --- */
.lp-hw {
	position: relative;
	width: 100%;
	height: 660px;
	/* Satellites flank the CTA row, never the lead: the stage starts below
	   the paragraph, so a shorter headline can't pull plates over the copy. */
	margin-top: -104px;
	text-align: left;
	pointer-events: none;
}
.lp-hw > * {
	pointer-events: auto;
}
.lp-hw-win {
	position: absolute;
	background: var(--lp-card);
	border: 1px solid var(--lp-hair);
	cursor: grab;
	touch-action: pan-y;
	user-select: none;
}
.lp-hw-win.drag {
	cursor: grabbing;
	z-index: 9;
	border-color: var(--lp-red);
}
@media (hover: hover) {
	.lp-hw-win:hover {
		border-color: color-mix(in srgb, var(--lp-red) 40%, var(--lp-hair));
	}
}
.lp-hw-win.app {
	/* centered via margin, not transform, so `translate` stays free for drag */
	left: 50%;
	width: min(640px, 54%);
	margin-left: calc(min(640px, 54%) / -2);
	top: 226px;
	z-index: 2;
}
.lp-hw-win.slack {
	left: 0;
	top: 0;
	width: 264px;
	z-index: 3;
}
.lp-hw-win.term {
	right: 0;
	top: 0;
	width: 288px;
	z-index: 3;
}
.lp-hw-win.sdk {
	left: 0;
	bottom: 0;
	width: 268px;
	z-index: 1;
}

/* --- browser / terminal window chrome --- */
.lp-hw-chrome {
	display: flex;
	align-items: center;
	gap: 10px;
	padding: 8px 11px;
	border-bottom: 1px solid var(--lp-hair);
	background: var(--lp-canvas);
}
.lp-hw-chrome .tl {
	display: inline-flex;
	gap: 5px;
	flex: none;
}
/* Traffic lights are round everywhere; as flat squares they read as empty
   checkboxes rather than window controls, so this is the one place the
   radius-0 rule gives way to the convention. */
.lp-hw-chrome .tl i {
	width: 8px;
	height: 8px;
	border-radius: 50%;
	background: var(--lp-hair);
}
.lp-hw-chrome .url {
	flex: 1;
	min-width: 0;
	font-family: var(--font-mono);
	font-size: 9.5px;
	letter-spacing: 0.02em;
	color: var(--lp-ink2);
	background: var(--lp-card);
	border: 1px solid var(--lp-hair);
	padding: 4px 9px;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}
.lp-hw-chrome .url .pth {
	color: var(--lp-mut);
}

.lp-hw-chrome .avs .lp-hw-av + .lp-hw-av {
	margin-left: -5px;
}
/* dark variant: the terminal window */
.lp-hw-chrome.dk {
	background: #16161a;
	border-bottom-color: #2a2a30;
}
.lp-hw-chrome.dk .tl i {
	background: #3a3a42;
}

/* --- chrome bar --- */
.lp-hw-bar {
	display: flex;
	align-items: center;
	gap: 9px;
	padding: 9px 12px;
	border-bottom: 1px solid var(--lp-hair);
	font-family: var(--font-mono);
	font-size: 9.5px;
	letter-spacing: 0.07em;
	text-transform: uppercase;
	color: var(--lp-ink2);
	background: var(--lp-canvas);
}
.lp-hw-bar .bmk {
	display: inline-flex;
	align-items: center;
	color: var(--lp-ink2);
	flex: none;
}
.lp-hw-bar .bmk .lp-bm {
	width: 11px;
	height: 11px;
}
.lp-hw-bar .dot {
	width: 6px;
	height: 6px;
	background: var(--lp-red);
	flex: none;
}
.lp-hw-bar .nm {
	color: var(--lp-ink);
	white-space: nowrap;
}

.lp-hw-bar .sp {
	flex: 1;
}

.lp-hw-bar .mono {
	color: var(--lp-mut);
	white-space: nowrap;
}

.lp-hw-bar .avs .lp-hw-av + .lp-hw-av {
	margin-left: -5px;
}
.lp-hw-av {
	width: 17px;
	height: 17px;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	font-family: var(--font-mono);
	font-size: 8px;
	letter-spacing: 0;
	text-transform: none;
	color: var(--lp-ink2);
	background: var(--lp-canvas);
	border: 1px solid var(--lp-hair);
	flex: none;
}
.lp-hw-av.t {
	background: var(--lp-red);
	color: var(--lp-on-red);
	border-color: var(--lp-red);
}

/* --- app body: sidebar + main --- */
/* Fixed height so swapping panes doesn't resize the window under the
   cursor. Tall enough to fit the sidebar's longest state (Context
   expanded, 346px) so no pane needs to scroll. */
.lp-hw-split {
	display: grid;
	grid-template-columns: 140px minmax(0, 1fr);
	height: 352px;
}
.lp-hw-main {
	overflow: hidden;
}
.lp-hw-side {
	display: flex;
	flex-direction: column;
	gap: 5px;
	padding: 11px 10px;
	border-right: 1px solid var(--lp-hair);
	font-size: 11px;
	color: var(--lp-ink2);
	min-width: 0;
	overflow-x: hidden;
	overflow-y: auto;
	scrollbar-width: none;
}
.lp-hw-side::-webkit-scrollbar {

