import type { ComponentChildren } from "preact";
import { Mark } from "../landing/brand-marks";

/**
 * The app plate: browser chrome, the product's sidebar, and one pane.
 *
 * Shared by the hero stage and by blog figures, so a screenshot of the
 * product in either place is the same markup styled by the same rules —
 * theme-aware and responsive, rather than a dark-mode PNG that drifts the
 * next time the app changes.
 *
 * Everything is config: pass `onSelect` to get an interactive sidebar (the
 * hero), omit it to get an inert one (a figure).
 */

export type NavKey = "activity" | "connect" | "memory";

export type SideRow =
	| { kind: "nav"; id: string; k: NavKey; label: string }
	| { kind: "group"; id: string; label: string }
	| { kind: "agent"; id: string; label: string }
	| { kind: "conv"; id: string; mark?: string; label: string };

/**
 * Sidebar glyphs, matching the icons the app uses for each nav row
 * (lucide: Activity, Plug, Boxes). Stroked, not filled, like the source.
 */
export function NavIcon({ k }: { k: NavKey }) {
	const d =
		k === "activity"
			? "M22 12h-2.48a2 2 0 0 0-1.93 1.46l-2.35 8.36a.25.25 0 0 1-.48 0L9.24 2.18a.25.25 0 0 0-.48 0l-2.35 8.36A2 2 0 0 1 4.49 12H2"
			: k === "connect"
				? "M12 22v-5M9 8V2M15 8V2M18 8v5a4 4 0 0 1-4 4h-4a4 4 0 0 1-4-4V8Z"
				: "M2.97 12.92A2 2 0 0 0 2 14.63v3.24a2 2 0 0 0 .97 1.71l3 1.8a2 2 0 0 0 2.06 0L12 19.16l3.97 2.22a2 2 0 0 0 2.06 0l3-1.8a2 2 0 0 0 .97-1.71v-3.24a2 2 0 0 0-.97-1.71L18 10.76V7.24a2 2 0 0 0-.97-1.71l-3-1.8a2 2 0 0 0-2.06 0l-3 1.8A2 2 0 0 0 8 7.24v3.52ZM12 8 8 10.5M12 8l4 2.5M12 8v4M2 14.5l4 2.5M22 14.5 18 17M12 19v-4";
	return (
		<svg
			aria-hidden="true"
			class="lp-hw-ni"
			fill="none"
			stroke="currentColor"
			stroke-linecap="round"
			stroke-linejoin="round"
			stroke-width="2"
			viewBox="0 0 24 24"
		>
			<path d={d} />
		</svg>
	);
}

/** The agent's own mark — a bot face, so an agent row reads as software. */
export function AgentGlyph() {
	return (
		<svg
			aria-hidden="true"
			class="lp-hw-ni"
			fill="none"
			stroke="currentColor"
			stroke-linecap="round"
			stroke-linejoin="round"
			stroke-width="2"
			viewBox="0 0 24 24"
		>
			<path d="M12 8V4H8M4 8h16v12H4zM2 14h2M20 14h2M15 13v2M9 13v2" />
		</svg>
	);
}

/** Sessions opened over the API have no brand, so they carry a code glyph. */
export function CodeGlyph() {
	return (
		<svg
			aria-hidden="true"
			class="lp-bm"
			fill="none"
			stroke="currentColor"
			stroke-linecap="round"
			stroke-linejoin="round"
			stroke-width="2"
			viewBox="0 0 24 24"
		>
			<path d="m8 16-4-4 4-4M16 8l4 4-4 4" />
		</svg>
	);
}

/** The workspace switcher the app pins to the top of its sidebar. */
function OrgRow({ org }: { org: string }) {
	return (
		<span class="org">
			<span class="lp-hw-av">{org.slice(0, 1).toUpperCase()}</span>
			<span class="wn">{org}</span>
			<span aria-hidden="true" class="cv-i">
				⌄
			</span>
			<span class="sp" />
			<svg
				aria-hidden="true"
				fill="none"
				stroke="currentColor"
				stroke-linecap="round"
				stroke-width="2"
				viewBox="0 0 24 24"
			>
				<circle cx="11" cy="11" r="7" />
				<path d="m20 20-3.5-3.5" />
			</svg>
			<svg
				aria-hidden="true"
				fill="none"
				stroke="currentColor"
				stroke-linejoin="round"
				stroke-width="2"
				viewBox="0 0 24 24"
			>
				<rect height="18" rx="2" width="18" x="3" y="3" />
				<path d="M9 3v18" />
			</svg>
		</span>
	);
}

/** One sidebar row's contents, independent of whether it is clickable. */
function RowBody({ row }: { row: SideRow }) {
	if (row.kind === "nav")
		return (
			<>
				<NavIcon k={row.k} />
				{row.label}
			</>
		);
	if (row.kind === "agent")
		return (
			<>
				<AgentGlyph />
				{row.label}
			</>
		);
	return (
		<>
			<span class="mk">{row.mark ? <Mark id={row.mark} /> : <CodeGlyph />}</span>
			{row.label}
		</>
	);
}

const ROW_CLASS = { nav: "ic", agent: "ag", conv: "cv" } as const;

export function AppPlate({
	org,
	path,
	rows,
	selected,
	onSelect,
	children,
}: {
	/** Workspace name, shown in the switcher and used for the avatar letter. */
	org: string;
	/** Route after the host, e.g. `/acme/activity`. */
	path: string;
	rows: SideRow[];
	/** `id` of the row to mark current. */
	selected: string;
	/** Omit for an inert plate; pass to make the sidebar rows tabs. */
	onSelect?: (id: string) => void;
	/** The pane filling the main column. */
	children: ComponentChildren;
}) {
	return (
		<>
			<div class="lp-hw-chrome">
				<span class="tl">
					<i />
					<i />
					<i />
				</span>
				<span class="url">
					app.lobu.ai<span class="pth">{path}</span>
				</span>
			</div>
			<div class="lp-hw-split">
				<div
					aria-label="Lobu app views"
					class="lp-hw-side"
					role={onSelect ? "tablist" : undefined}
				>
					<OrgRow org={org} />
					{rows.map((row) => {
						if (row.kind === "group")
							return (
								<span class="grp" key={row.id}>
									{row.label}
								</span>
							);
						const cls = `${ROW_CLASS[row.kind]} ${selected === row.id ? "sel" : ""}`;
						return onSelect ? (
							<button
								aria-selected={selected === row.id}
								class={cls}
								key={row.id}
								onClick={() => onSelect(row.id)}
								role="tab"
								type="button"
							>
								<RowBody row={row} />
							</button>
						) : (
							<span class={cls} key={row.id}>
								<RowBody row={row} />
							</span>
						);
					})}
				</div>
				<div class="lp-hw-main">{children}</div>
			</div>
		</>
	);
}

