input.content:
import { Mark } from "../landing/brand-marks";

/**
 * Activity — the event stream, where work needing approval surfaces.
 *
 * Shaped after the app's Activity page rather than a stylised list: the same
 * filter bar, item count, dot-rail timeline, key/value payload block, and an
 * approval card whose fields are rendered from the JSON schema the event
 * carries. Rows come in as config so the same pane can show a hero's teaser
 * or a blog figure's specific case.
 */

/** One field of a proposed action, rendered from the event's input schema. */
export type ActivityField = {
	label: string;
	value: string;
	/** Draws the red asterisk the app puts on a required field. */
	required?: boolean;
	/** Renders `value` as placeholder text rather than an entered value. */
	placeholder?: boolean;
};

export type ActivityEvent = {
	id: string;
	/** Relative time, as the app prints it. */
	t: string;
	title: string;
	/** Action rows carry the lightning glyph. */
	bolt?: boolean;
	/** Brand mark before the title, for a row a connector ingested. */
	mark?: string;
	/** Trailing note after the title, e.g. `on GitHub (App install)`. */
	on?: string;
	/** Badge at the end of the header row, e.g. `Rejected`. */
	tag?: string;
	/** Provenance line under the header. */
	by?: string;
	/** Payload block for an audit or config event. */
	kv?: { k: string; v: string }[];
	fields?: ActivityField[];
	/** Renders the confirm/reject pair under the fields. */
	actions?: boolean;
};

export type ActivityConfig = {
	/** Segmented control; the first entry is the selected one. */
	tabs: string[];
	filters: { label: string; value: string; on?: boolean }[];
	count: string;
	events: ActivityEvent[];
	/** Two facts split across the pane footer. */
	foot?: { left: string; right: string };
};

export function ActivityPane({ cfg }: { cfg: ActivityConfig }) {
	return (
		<>
			<div class="lp-hw-actbar">
				<span class="seg">
					{cfg.tabs.map((t, i) => (
						<span class={i === 0 ? "sel" : ""} key={t}>
							{t}
						</span>
					))}
				</span>
				{cfg.filters.map((f) => (
					<span class={`fc ${f.on ? "on" : ""}`} key={f.label}>
						{f.label} <b>{f.value}</b>
					</span>
				))}
				<span class="sp" />
				<span class="ct">{cfg.count}</span>
			</div>
			{/* Both halves of the log: what the agent proposed and what your
			    systems did, in one stream with the run stamped on each row. */}
			<div class="lp-hw-act">
				{cfg.events.map((e) => (
					<div class="ev" key={e.id}>
						<span class="rail" />
						<span>
							<span class="t">{e.t}</span>
							<span class="hd">
								{e.bolt ? <BoltGlyph /> : null}
								<span class="ti">
									{e.mark ? (
										<span class="src">
											<Mark id={e.mark} />
										</span>
									) : null}
									{e.title}
								</span>
								{e.on ? <span class="on">{e.on}</span> : null}
								{e.tag ? <span class="tag">{e.tag}</span> : null}
							</span>
							{e.by ? <span class="by">{e.by}</span> : null}
							{e.kv ? (
								<span class="kv">
									{e.kv.map((r) => (
										<>
											<span class="k" key={`k${r.k}`}>
												{r.k}
											</span>
											<span class="v" key={`v${r.k}`}>
												{r.v}
											</span>
										</>
									))}
								</span>
							) : null}
							{e.fields?.map((f) => (
								<span class="fld" key={f.label}>
									<span class="lb">
										{f.label} {f.required ? <i>*</i> : null}
									</span>
									<span class={`in ${f.placeholder ? "ph" : ""}`}>{f.value}</span>
								</span>
							))}
							{e.actions ? (
								<span class="btns">
									<span class="b go">
										<i aria-hidden="true">✓</i>Confirm
									</span>
									<span class="b">
										<i aria-hidden="true">✕</i>Reject
									</span>
								</span>
							) : null}
						</span>
					</div>
				))}
			</div>
			{cfg.foot ? (
				<div class="lp-hw-foot">
					<span class="mono">{cfg.foot.left}</span>
					<span class="sp" />
					<span class="mono rd">{cfg.foot.right}</span>
				</div>
			) : null}
		</>
	);
}

/** The lightning glyph the app puts on an action row. */
function BoltGlyph() {
	return (
		<svg
			aria-hidden="true"
			class="lp-hw-bolt"
			fill="none"
			stroke="currentColor"
			stroke-linecap="round"
			stroke-linejoin="round"
			stroke-width="2"
			viewBox="0 0 24 24"
		>
			<path d="M13 2 3 14h9l-1 8 10-12h-9l1-8Z" />
		</svg>
	);
}

