import type { ComponentChildren } from "preact";

/**
 * A figure whose contents are the live app plate rather than a screenshot.
 *
 * Same caption plate as the landing figure cards (thin border, mono corner
 * ticks, number and label underneath). The plate inside renders from config
 * and inherits the reader's theme, so a figure cannot go stale against the
 * product the way a checked-in PNG does.
 */

const TICKS = [
	"left-0 top-0 -translate-x-1/2 -translate-y-1/2",
	"right-0 top-0 translate-x-1/2 -translate-y-1/2",
	"left-0 bottom-0 -translate-x-1/2 translate-y-1/2",
	"right-0 bottom-0 translate-x-1/2 translate-y-1/2",
];

export function AppFigure(props: {
	/** Figure number plate, e.g. "FIG_01". */
	n: string;
	/** Short caption after the number. */
	label: string;
	/** Optional right-aligned note (surface, route, environment). */
	extra?: string;
	/** Alternative text for the plate, which is decorative markup to a reader. */
	alt: string;
	children: ComponentChildren;
}) {
	return (
		<figure class="my-7">
			<div
				class="relative border p-1.5"
				style={{
					borderColor: "var(--color-page-border)",
					background: "var(--color-page-surface, transparent)",
				}}
			>
				{TICKS.map((pos) => (
					<span
						aria-hidden="true"
						class={`absolute ${pos} font-mono text-[9px] leading-none`}
						key={pos}
						style={{ color: "var(--color-page-text-muted)" }}
					>
						+
					</span>
				))}
				{/* `st` puts the plate in normal flow: no stage, no drag. */}
				<div aria-label={props.alt} class="lp-hw-win app st" role="img">
					{props.children}
				</div>
			</div>
			<figcaption
				class="mt-2 flex flex-wrap items-baseline gap-x-2 font-mono text-[10px] uppercase tracking-wider"
				style={{ color: "var(--color-page-text-muted)" }}
			>
				<span style={{ color: "var(--color-tg-accent)" }}>{props.n}</span>
				<span>{props.label}</span>
				{props.extra ? <span class="ms-auto">{props.extra}</span> : null}
			</figcaption>
		</figure>
	);
}

