import type { ComponentChildren } from "preact";
import { useState } from "preact/hooks";
import { Mark } from "../landing/brand-marks";

/**
 * The Behaviors pane: one row per Behavior, expanding into what wakes it, the
 * prompt it runs, and what it leaves behind.
 *
 * Config-driven like {@link ActivityPane}, so the hero and a blog figure are
 * the same markup with different content.
 */

export type Behavior = {
	name: string;
	/** What wakes it: connector events, or a clock when `mark` is absent. */
	triggers: { mark?: string; label: string }[];
	goal: ComponentChildren;
	/** Entity changes and appended events, in the order the run writes them. */
	writes: { subject: string; rest: string }[];
};

export type BehaviorsConfig = {
	/** Right-hand toolbar note, e.g. the owning agent and a count. */
	meta: string;
	behaviors: Behavior[];
	/** Row expanded on first render; -1 for all collapsed. */
	open?: number;
	foot?: { left: string; right: string };
};

export function BehaviorsPane({ cfg }: { cfg: BehaviorsConfig }) {
	const [open, setOpen] = useState(cfg.open ?? 0);
	return (
		<>
			<div class="lp-hw-toolbar">
				<span class="q">Behaviors</span>
				<span class="sp" />
				<span class="mono">{cfg.meta}</span>
			</div>
			<div class="lp-hw-beh">
				{cfg.behaviors.map((b, i) => (
					<div class={`bhg ${open === i ? "open" : ""}`} key={b.name}>
						<button
							aria-expanded={open === i}
							class={`bh ${open === i ? "on" : ""}`}
							onClick={() => setOpen(open === i ? -1 : i)}
							type="button"
						>
							<span class="cv-i">▾</span>
							<span class="nm">{b.name}</span>
							<span class="tg">
								{b.triggers.length}{" "}
								{b.triggers.length === 1 ? "trigger" : "triggers"}
							</span>
						</button>
						{open === i ? (
							<>
								{/* what wakes it: connector events, not just a clock */}
								<div class="trg">
									<span class="lbl">Triggers</span>
									{b.triggers.map((t) => (
										<span class="tr" key={t.label}>
											{t.mark ? (
												<span class="mk">
													<Mark id={t.mark} />
												</span>
											) : (
												<span class="cl">⏱</span>
											)}
											{t.label}
										</span>
									))}
								</div>
								<div class="goal">{b.goal}</div>
								{/* and what it leaves behind: merged entities plus new events */}
								<div class="wrt">
									<span class="lbl">Writes</span>
									{b.writes.map((w) => (
										<span class="w" key={w.subject}>
											<b>{w.subject}</b> · {w.rest}
										</span>
									))}
								</div>
							</>
						) : null}
					</div>
				))}
			</div>
			{cfg.foot ? (
				<div class="lp-hw-foot">
					<span class="mono">{cfg.foot.left}</span>
					<span class="sp" />
					<span class="mono rd">{cfg.foot.right}</span>
				</div>
			) : null}
		</>
	);
}

