export type Behavior = {
	name: string;
	/** What wakes it: connector events, or a clock when `mark` is absent. */
	triggers: { mark?: string; label: string }[];
	/** The prompt, with the load-bearing nouns wrapped in `*asterisks*`. */
	goal: string;
	/** Entity changes and appended events, in the order the run writes them. */
	writes: { subject: string; rest: string }[];
};

/**
 * Bolds `*emphasised*` runs.
 *
 * The prompt has to be a plain string rather than JSX: a vnode written inside
 * a prop object in MDX never crosses the Astro-to-Preact boundary, so it
 * renders as nothing. A string also keeps the config serializable.
 */
function Emphasised({ text }: { text: string }) {
	return (
		<>
			{text.split(/\*([^*]+)\*/).map((part, i) =>
				i % 2 ? (
					// biome-ignore lint/suspicious/noArrayIndexKey: split output is positional
					<b key={i}>{part}</b>
				) : (
					part
				),
			)}
		</>
	);
}

